// Recast's and Detour's own limits (not starting values):
/** detailSampleDist below this becomes 0 and crashes buildPolyMeshDetail (MAP recast §7.6). */
const DETAIL_SAMPLE_DIST_MIN = 0.9;
/** Recast's tiled sample pads every tile by the agent radius + 3 voxels (the generators' borderSize). */
const BORDER_PAD_VOX = 3;
/** Detour's 32-bit poly refs: tile and polygon bits share 22 bits, at most 14 for tiles (MAP recast §3.3). */
const REF_TILE_POLY_BITS = 22;
const REF_MAX_TILE_BITS = 14;
/** Every walkable polygon gets area 0 and flags 1, as the library's generators do; the query filter includes all flags. */
const POLY_FLAGS_WALK = 1;
const QUERY_INCLUDE_ALL = 0xffff;
/** isWalkable's polygon query buffer: a walkReachM box meets a handful of polygons. */
const WALK_QUERY_MAX_POLYS = 256;
/**
 * "Within walkReachM" is measured with this tolerance (m). Polygon vertices lie on the voxel grid and walk cells are the
 * voxels, so an axis-aligned polygon edge sits exactly 0.1, 0.3 or 0.5 m from a cell centre: without it, float rounding
 * (Detour's float32 against this file's float64) would decide those ties differently in the bitmap and in isWalkable.
 */
const WALK_REACH_TOL = 1e-4;

/** A layer's voxel configuration, fixed when the layer is built. */
interface LayerSpec {
  layer: NavLayer;
  index: number;
  cs: number;
  ch: number;
  slopeDeg: number;
  radiusVox: number;
  heightVox: number;
  climbVox: number;
  tileVox: number;
  borderVox: number;
  maxEdgeVox: number;
  maxSimplificationError: number;
  minRegionArea: number;
  mergeRegionArea: number;
  nvp: number;
  detailSampleDist: number;
  detailSampleMaxError: number;
  /** m: a tile's side and its border. */
  tcs: number;
  border: number;
  origX: number;
  origZ: number;
  minY: number;
  maxY: number;
  tilesX: number;
  tilesZ: number;
  tileBits: number;
  polyBits: number;
  /**
   * Ruler layer: an extruded blocker's height, one voxel under walkableHeight (§7 says "up to walkableHeight"; at exactly
   * that height the floor inside a wide extrusion would have the headroom to count as walkable).
   */
  extrudeM: number | null;
}

/** One layer's live recast objects and per-tile state. */
interface LayerRt {
  spec: LayerSpec;
  navMesh: NavMesh;
  query: NavMeshQuery;
  /** Per tile, bumped on every build and rebuild of it. */
  versions: Uint32Array;
  /** Detour tile slot → tile index (ty·tilesX + tx), −1 when free. */
  slotTile: Int32Array;
  dirty: Set<number>;
  /** Human layer: per tile, the walk and blocker bitmaps (1 bit per cs cell, row-major along z). */
  walk: Uint8Array[] | null;
  block: Uint8Array[] | null;
}

/** A path as positions (poly refs never leave this file). */
export interface NavPath {
  points: V3[];
  /** The path reaches the goal: not a partial path, ending within goalTolM of `to` (MAP recast §7.2). */
  complete: boolean;
  /** The tiles its corridor crosses (sorted) and their versions now: re-path when one changes (§6.5). */
  tiles: number[];
  versions: number[];
}

const NO_PATH = (): NavPath => ({ points: [], complete: false, tiles: [], versions: [] });

export class NavSystem {
  readonly world: World;
  /** Tiles that failed to build (a recast error): left empty, counted here for the dev panel and tests. */
  buildFailures = 0;
  /** How many times each reason marked tiles dirty (dev read-out). */
  readonly dirtyReasons = new Map<string, number>();

  private layers: LayerRt[] | null = null;
  private disposed = false;
  /** The baked set: entity id → its navmesh record. */
  private readonly baked = new Map<number, NavEntityInput>();
  private bakedSorted: NavEntityInput[] | null = null;
  /** Terrain tile versions and heights as the navmesh last saw them. */
  private seenVersion: Uint32Array = new Uint32Array(0);
  private seenHeights: Float32Array[] = [];

  constructor(world: World) {
    this.world = world;
  }

  /** Whether build() has run (and dispose() hasn't). */
  get built(): boolean {
    return this.layers !== null;
  }

  // -------------------------------------------------------------------------
  // Build and rebuild
  // -------------------------------------------------------------------------

  /**
   * Full tiled build of both layers (createWorld, load) from the current terrain and entities: the baked set is taken
   * afresh, every tile is built in (ty, tx) order, every tile version is bumped and the dirty queue is cleared.
   */
  build(w: World): void {
    this.alive('build');
    if (w !== this.world) throw new Error('NavSystem.build: a NavSystem builds the world it was made for');
    const sc = recastScratch();
    const old = this.layers;
    this.freeLayers();
    this.baked.clear();
    this.bakedSorted = null;
    const restTicks = PHYSICS_TUNING.restTicks;
    for (const e of w.entities.all()) {
      const pres = navPresence(e, restTicks);
      if (pres === 'static' || pres === 'resting') this.baked.set(e.id, this.bake(e));
    }
    this.seeTerrain();
    const t = w.terrain;
    let lo = Infinity;
    let hi = -Infinity;
    for (const o of t.original) {
      for (let i = 0; i < o.length; i++) {
        if (o[i] < lo) lo = o[i];
        if (o[i] > hi) hi = o[i];
      }
    }
    const minY = lo - TERRAIN_TUNING.maxDigDepthM - NAV_TUNING.boundsBelowM;
    const maxY = hi + NAV_TUNING.boundsAboveM;
    const layers: LayerRt[] = [];
    try {
      NAV_LAYERS.forEach((layer, index) => {
        const spec = layerSpec(layer, index, t, minY, maxY);
        const navMesh = new NavMesh();
        const params = NavMeshParams.create({
          orig: { x: spec.origX, y: spec.minY, z: spec.origZ },
          tileWidth: spec.tcs,
          tileHeight: spec.tcs,
          maxTiles: 1 << spec.tileBits,
          maxPolys: 1 << spec.polyBits,
        });
        const ok = navMesh.initTiled(params);
        Raw.destroy(params.raw);
        if (!ok) {
          navMesh.destroy();
          throw new Error(`NavSystem.build: could not initialise the ${layer} navmesh`);
        }
        const query = new NavMeshQuery(navMesh, { maxNodes: NAV_TUNING.maxNodes });
        query.defaultFilter.includeFlags = QUERY_INCLUDE_ALL;
        query.defaultFilter.excludeFlags = 0;
        const n = spec.tilesX * spec.tilesZ;
        const prev = old?.[index];
        const versions = prev && prev.versions.length === n ? prev.versions : new Uint32Array(n);
        const human = layer === 'human';
        const bytes = Math.ceil((spec.tileVox * spec.tileVox) / 8);
        layers.push({
          spec,
          navMesh,
          query,
          versions,
          slotTile: new Int32Array(1 << spec.tileBits).fill(-1),
          dirty: new Set(),
          walk: human ? Array.from({ length: n }, () => new Uint8Array(bytes)) : null,
          block: human ? Array.from({ length: n }, () => new Uint8Array(bytes)) : null,
        });
      });
      this.layers = layers;
      for (const L of layers) {
        for (let tz = 0; tz < L.spec.tilesZ; tz++) for (let tx = 0; tx < L.spec.tilesX; tx++) this.rebuildTile(L, tx, tz, sc);
      }
    } catch (err) {
      this.layers = layers;
      this.freeLayers();
      throw err;
    }
  }

  /**
   * Phase 16: the scan (the baked set and terrain brought up to date, their changes marked dirty), then up to
   * tilesPerTick dirty tiles per layer, sorted (layer, ty, tx), rebuilt synchronously from the current state.
   */
  rebuildDirty(): void {
    this.alive('rebuildDirty');
    if (!this.layers) return;
    this.scan();
    let sc: Scratch | null = null;
    for (const L of this.layers) {
      if (L.dirty.size === 0) continue;
      const k = Math.max(0, Math.floor(NAV_TUNING[L.spec.layer].tilesPerTick));
      if (k === 0) continue;
      const next = [...L.dirty].sort((a, b) => a - b).slice(0, k);
      sc ??= recastScratch();
      for (const tile of next) {
        L.dirty.delete(tile);
        this.rebuildTile(L, tile % L.spec.tilesX, Math.floor(tile / L.spec.tilesX), sc);
      }
    }
  }

  /**
   * Marks every tile whose grown rect (the tile ± Recast's border) overlaps `aabb`, on both layers (§7). `why` names the
   * change for the dev read-out (dirtyReasons).
   */
  markDirty(aabb: { min: V3; max: V3 }, why: string): void {
    this.alive('markDirty');
    this.dirtyReasons.set(why, (this.dirtyReasons.get(why) ?? 0) + 1);
    if (!this.layers) return;
    for (const L of this.layers) {
      const s = L.spec;
      const tx0 = Math.max(0, Math.ceil((aabb.min.x - s.border - s.origX) / s.tcs - 1));
      const tx1 = Math.min(s.tilesX - 1, Math.floor((aabb.max.x + s.border - s.origX) / s.tcs));
      const tz0 = Math.max(0, Math.ceil((aabb.min.z - s.border - s.origZ) / s.tcs - 1));
      const tz1 = Math.min(s.tilesZ - 1, Math.floor((aabb.max.z + s.border - s.origZ) / s.tcs));
      for (let tz = tz0; tz <= tz1; tz++) for (let tx = tx0; tx <= tx1; tx++) L.dirty.add(tz * s.tilesX + tx);
    }
  }

  /** (layer, ty, tx) of every dirty tile, sorted: the save's queue. */
  dirtyQueue(): [number, number, number][] {
    const out: [number, number, number][] = [];
    if (!this.layers) return out;
    for (const L of this.layers) {
      for (const t of [...L.dirty].sort((a, b) => a - b)) out.push([L.spec.index, Math.floor(t / L.spec.tilesX), t % L.spec.tilesX]);
    }
    return out;
  }

  /** Restores the save's dirty queue (the loader, after build). Entries outside the layers' tile grids are refused. */
  restoreDirty(q: [number, number, number][]): void {
    this.alive('restoreDirty');
    if (q.length === 0) return;
    const layers = this.layers;
    if (!layers) throw new Error('NavSystem.restoreDirty: build() first');
    for (const [l, ty, tx] of q) {
      const L = layers[l];
      if (!L || !Number.isInteger(ty) || !Number.isInteger(tx) || tx < 0 || ty < 0 || tx >= L.spec.tilesX || ty >= L.spec.tilesZ) {
        throw new Error(`NavSystem.restoreDirty: no tile (${l}, ${ty}, ${tx})`);
      }
    }
    for (const [l, ty, tx] of q) layers[l].dirty.add(ty * layers[l].spec.tilesX + tx);
  }

  // -------------------------------------------------------------------------
  // Queries (positions only)
  // -------------------------------------------------------------------------

  /**
   * A path from `from` to `to` on `layer`, as positions: both ends snapped to the nearest polygon within the layer's
   * half-extents (no polygon: no path), the corridor found with A*, the straight path string-pulled along it.
   * `complete` is false for a partial path (recast's DT_PARTIAL_RESULT, a corridor that stops short of the goal's
   * polygon) and when the last point lies farther than goalTolM from `to` on the ground plane (§7). `tiles` are the
   * tiles of every corridor polygon, sorted, with their versions now.
   */
  findPath(layer: NavLayer, from: V3, to: V3): NavPath {
    const L = this.layer(layer, 'findPath');
    const q = L.query;
    const he = halfExtentsOf(layer);
    const s = q.findNearestPoly(from, { halfExtents: he });
    if (!s.success || s.nearestRef === 0) return NO_PATH();
    const e = q.findNearestPoly(to, { halfExtents: he });
    if (!e.success || e.nearestRef === 0) return NO_PATH();
    const fp = q.findPath(s.nearestRef, e.nearestRef, s.nearestPoint, e.nearestPoint, { maxPathPolys: Math.max(1, Math.floor(NAV_TUNING.maxPathPolys)) });
    try {
      const n = fp.polys.size;
      if (!fp.success || n === 0) return NO_PATH();
      const corridor: number[] = [];
      for (let i = 0; i < n; i++) corridor.push(fp.polys.get(i));
      const lastPoly = corridor[n - 1];
      let end = e.nearestPoint;
      if (lastPoly !== e.nearestRef) {
        const c = q.closestPointOnPoly(lastPoly, to);
        if (!c.success) return NO_PATH();
        end = c.closestPoint;
      }
      const sp = q.findStraightPath(s.nearestPoint, end, fp.polys, { maxStraightPathPoints: Math.max(2, Math.floor(NAV_TUNING.maxStraightPoints)) });
      const points: V3[] = [];
      try {
        if (!sp.success) return NO_PATH();
        for (let i = 0; i < sp.straightPathCount; i++) {
          points.push({ x: sp.straightPath.get(i * 3), y: sp.straightPath.get(i * 3 + 1), z: sp.straightPath.get(i * 3 + 2) });
        }
      } finally {
        sp.straightPath.destroy();
        sp.straightPathFlags.destroy();
        sp.straightPathRefs.destroy();
      }
      if (points.length === 0) return NO_PATH();
      const partial = statusDetail(fp.status, Detour.DT_PARTIAL_RESULT) || lastPoly !== e.nearestRef;
      const last = points[points.length - 1];
      const complete = !partial && Math.hypot(last.x - to.x, last.z - to.z) <= NAV_TUNING[layer].goalTolM;
      const tiles = [...new Set(corridor.map((r) => this.tileOfRef(L, r)).filter((t) => t >= 0))].sort((a, b) => a - b);
      return { points, complete, tiles, versions: tiles.map((t) => L.versions[t]) };
    } finally {
      fp.polys.destroy();
    }
  }

  /**
   * A walkability ray along the navmesh surface from the polygon nearest `from` toward `to` (2-D: `to.y` is ignored).
   * `clear` when it reaches `to`; else `t` (0..1) is how far along it a wall was met. No polygon near `from`: not clear,
   * t 0.
   */
  raycast(layer: NavLayer, from: V3, to: V3): { clear: boolean; t: number } {
    const L = this.layer(layer, 'raycast');
    const s = L.query.findNearestPoly(from, { halfExtents: halfExtentsOf(layer) });
    if (!s.success || s.nearestRef === 0) return { clear: false, t: 0 };
    const r = L.query.raycast(s.nearestRef, s.nearestPoint, to);
    if (!r.success) return { clear: false, t: 0 };
    return r.t >= 1 ? { clear: true, t: 1 } : { clear: false, t: Math.max(0, r.t) };
  }

  /** The nearest point on the layer's navmesh within its half-extents; null when nearestRef === 0 (MAP recast §7.1). */
  nearest(layer: NavLayer, p: V3): V3 | null {
    const L = this.layer(layer, 'nearest');
    const r = L.query.findNearestPoly(p, { halfExtents: halfExtentsOf(layer) });
    if (!r.success || r.nearestRef === 0) return null;
    return { x: r.nearestPoint.x, y: r.nearestPoint.y, z: r.nearestPoint.z };
  }

  /**
   * Whether (x, z) is walkable on `layer`, by a recast query: true when a polygon of the tile that holds the centre of
   * (x, z)'s cs cell lies within walkReachM of that centre on the ground plane. The human layer's walk bitmap holds the
   * same answer per cell, computed from the tile's polygons when the tile is built (§4.1; the bitmap test checks one
   * against the other).
   */
  isWalkable(layer: NavLayer, x: number, z: number): boolean {
    const L = this.layer(layer, 'isWalkable');
    const s = L.spec;
    const ci = Math.floor((x - s.origX) / s.cs);
    const cj = Math.floor((z - s.origZ) / s.cs);
    const tx = Math.floor(ci / s.tileVox);
    const tz = Math.floor(cj / s.tileVox);
    if (tx < 0 || tz < 0 || tx >= s.tilesX || tz >= s.tilesZ) return false;
    const tile = tz * s.tilesX + tx;
    const cx = s.origX + (ci + 0.5) * s.cs;
    const cz = s.origZ + (cj + 0.5) * s.cs;
    const reach = NAV_TUNING.walkReachM + WALK_REACH_TOL;
    const midY = (s.minY + s.maxY) / 2;
    const r = L.query.queryPolygons({ x: cx, y: midY, z: cz }, { x: reach, y: (s.maxY - s.minY) / 2 + s.ch, z: reach }, { maxPolys: WALK_QUERY_MAX_POLYS });
    if (!r.success) return false;
    for (const ref of r.polyRefs) {
      if (this.tileOfRef(L, ref) !== tile) continue;
      const c = L.query.closestPointOnPoly(ref, { x: cx, y: midY, z: cz });
      if (c.success && Math.hypot(c.closestPoint.x - cx, c.closestPoint.z - cz) <= reach) return true;
    }
    return false;
  }

  /** Bumped on every build and rebuild of the tile (0: never built). */
  tileVersion(layer: NavLayer, tile: number): number {
    const L = this.layers?.[NAV_LAYERS.indexOf(layer)];
    return L?.versions[tile] ?? 0;
  }

  /** The tile index (ty·tilesX + tx) of the layer's tile over (x, z); −1 outside the navmesh or before build. */
  tileAt(layer: NavLayer, x: number, z: number): number {
    const L = this.layers?.[NAV_LAYERS.indexOf(layer)];
    if (!L) return -1;
    const s = L.spec;
    const tx = Math.floor((x - s.origX) / s.tcs);
    const tz = Math.floor((z - s.origZ) / s.tcs);
    return tx < 0 || tz < 0 || tx >= s.tilesX || tz >= s.tilesZ ? -1 : tz * s.tilesX + tx;
  }

  /** The layer's tile grid: tiles along x and z, a tile's side (m) and the grid's min corner. */
  grid(layer: NavLayer): { tilesX: number; tilesZ: number; tileM: number; cellM: number; cellsPerTile: number; origX: number; origZ: number } {
    const s = this.layer(layer, 'grid').spec;
    return { tilesX: s.tilesX, tilesZ: s.tilesZ, tileM: s.tcs, cellM: s.cs, cellsPerTile: s.tileVox, origX: s.origX, origZ: s.origZ };
  }

  /** Human layer: 1 bit per cs (0.2 m) cell, bit j·cellsPerTile + i for cell (i along x, j along z); read-only. */
  walkBits(tile: number): Uint8Array {
    const L = this.layer('human', 'walkBits');
    const b = L.walk![tile];
    if (!b) throw new Error(`NavSystem.walkBits: no human tile ${tile}`);
    return b;
  }

  /** Fixed, anchored or ≥ blockerMinKg entity cells of the human tile, same layout, rebuilt with it; read-only. */
  blockBits(tile: number): Uint8Array {
    const L = this.layer('human', 'blockBits');
    const b = L.block![tile];
    if (!b) throw new Error(`NavSystem.blockBits: no human tile ${tile}`);
    return b;
  }

  /** NavWalkable's read: the human walk bit of the cell over (x, z) (false outside); true before any build. */
  walkBitAt(x: number, z: number): boolean {
    const L = this.layers?.[0];
    if (!L) return true;
    const c = cellOf(L.spec, x, z);
    return c !== null && bitAt(L.walk![c.tile], c.bit);
  }

  /**
   * NavWalkable's read: the first blocked human cell (row by row) whose centre lies within `pad` of (x, z), or whose
   * cell holds (x, z), as a box obstacle of one cell; null if none (or before any build).
   */
  blockedCellNear(x: number, z: number, pad: number): Obstacle | null {
    const L = this.layers?.[0];
    if (!L) return null;
    const s = L.spec;
    const r = Math.max(0, pad);
    const ci0 = Math.floor((x - r - s.origX) / s.cs);
    const ci1 = Math.floor((x + r - s.origX) / s.cs);
    const cj0 = Math.floor((z - r - s.origZ) / s.cs);
    const cj1 = Math.floor((z + r - s.origZ) / s.cs);
    const own = cellOf(s, x, z);
    for (let cj = cj0; cj <= cj1; cj++) {
      for (let ci = ci0; ci <= ci1; ci++) {
        const c = cellAt(s, ci, cj);
        if (!c || !bitAt(L.block![c.tile], c.bit)) continue;
        const cx = s.origX + (ci + 0.5) * s.cs;
        const cz = s.origZ + (cj + 0.5) * s.cs;
        const mine = own !== null && own.tile === c.tile && own.bit === c.bit;
        if (mine || Math.hypot(cx - x, cz - z) <= r) return { kind: 'box', x: cx, z: cz, hx: s.cs / 2, hz: s.cs / 2 };
      }
    }
    return null;
  }

  /** The layer's navmesh as recast exports it (tests: two builds of one state are byte-identical). */
  meshBytes(layer: NavLayer): Uint8Array {
    return exportNavMesh(this.layer(layer, 'meshBytes').navMesh);
  }

  /** The baked set's ids, in id order (tests and the dev panel). */
  bakedIds(): number[] {
    return this.sortedBaked().map((e) => e.id);
  }

  /** Frees both navmeshes and their queries (explicit destroy(); World.dispose, RF-24). */
  dispose(): void {
    if (this.disposed) return;
    this.freeLayers();
    this.baked.clear();
    this.bakedSorted = null;
    this.disposed = true;
  }

  // -------------------------------------------------------------------------
  // Internals
  // -------------------------------------------------------------------------

  private alive(what: string): void {
    if (this.disposed) throw new Error(`NavSystem.${what}: the navmesh was disposed`);
  }

  private layer(layer: NavLayer, what: string): LayerRt {
    this.alive(what);
    const i = NAV_LAYERS.indexOf(layer);
    if (i < 0) throw new Error(`NavSystem.${what}: unknown layer ${String(layer)}`);
    const L = this.layers?.[i];
    if (!L) throw new Error(`NavSystem.${what}: build() first`);
    return L;
  }

  private freeLayers(): void {
    const layers = this.layers;
    this.layers = null;
    if (!layers) return;
    for (const L of layers) {
      Raw.destroy(L.query.defaultFilter.raw);
      L.query.destroy();
      L.navMesh.destroy();
    }
  }

  private bake(e: Entity): NavEntityInput {
    return navBakeEntity(this.world, e, { blockerMinKg: NAV_TUNING.blockerMinKg, extrudeAboveAnkleM: NAV_TUNING.extrudeAboveAnkleM });
  }

  private sortedBaked(): NavEntityInput[] {
    this.bakedSorted ??= [...this.baked.values()].sort((a, b) => a.id - b.id);
    return this.bakedSorted;
  }

  /** The baked set and the terrain brought up to date; every change marked dirty (§7's dirty rules). */
  private scan(): void {
    const w = this.world;
    const restTicks = PHYSICS_TUNING.restTicks;
    const moveM = NAV_TUNING.dirtyMinMoveM;
    const turnDeg = NAV_TUNING.dirtyMinTurnDeg;
    const blockerMinKg = NAV_TUNING.blockerMinKg;
    for (const e of w.entities.all()) {
      const rec = this.baked.get(e.id);
      const pres = navPresence(e, restTicks);
      if (pres === 'static' || pres === 'resting') {
        if (!rec) {
          const b = this.bake(e);
          this.setBaked(b);
          this.markDirty(b.aabb, 'entity placed or at rest');
          continue;
        }
        const anchored = e.state === 'fixed' || e.state === 'anchored';
        const changed =
          e.shape !== rec.shape ||
          anchored !== rec.anchored ||
          isNavBlocker(w, e, blockerMinKg) !== rec.blocker ||
          Math.hypot(e.pose.p.x - rec.pose.p.x, e.pose.p.y - rec.pose.p.y, e.pose.p.z - rec.pose.p.z) > moveM ||
          turnDegrees(e.pose.q, rec.pose.q) > turnDeg;
        if (changed) {
          const b = this.bake(e);
          this.setBaked(b);
          this.markDirty(navUnionAabb(rec.aabb, b.aabb), 'entity moved or changed');
        }
      } else if (rec && (pres === 'gone' || rec.anchored)) {
        // Gone (picked up, stowed, tied…), or a fixed/anchored entity that started moving (a felling tree, a pulled
        // stake): its footprint clears at once. A free entity that starts moving keeps its record until it rests.
        this.deleteBaked(rec.id);
        this.markDirty(rec.aabb, pres === 'gone' ? 'entity removed' : 'entity unanchored');
      }
    }
    if (this.baked.size > 0) {
      for (const rec of this.sortedBaked()) {
        if (!w.entities.get(rec.id)) {
          this.deleteBaked(rec.id);
          this.markDirty(rec.aabb, 'entity removed');
        }
      }
    }
    this.scanTerrain();
  }

  private setBaked(b: NavEntityInput): void {
    this.baked.set(b.id, b);
    this.bakedSorted = null;
  }

  private deleteBaked(id: number): void {
    this.baked.delete(id);
    this.bakedSorted = null;
  }

  /** Terrain tiles whose version moved: the box of the vertices whose heights changed, grown by one cell, is dirty. */
  private scanTerrain(): void {
    const t = this.world.terrain;
    for (let tile = 0; tile < t.tileCount; tile++) {
      if (t.version[tile] === this.seenVersion[tile]) continue;
      this.seenVersion[tile] = t.version[tile];
      const H = t.heights[tile];
      const S = this.seenHeights[tile];
      const n1 = t.cells + 1;
      let r0 = Infinity;
      let r1 = -Infinity;
      let c0 = Infinity;
      let c1 = -Infinity;
      for (let i = 0; i < H.length; i++) {
        if (H[i] === S[i]) continue;
        const r = i % n1;
        const c = (i - r) / n1;
        if (r < r0) r0 = r;
        if (r > r1) r1 = r;
        if (c < c0) c0 = c;
        if (c > c1) c1 = c;
      }
      S.set(H);
      if (r1 < r0) continue;
      const tx = tile % t.tilesX;
      const tz = (tile - tx) / t.tilesX;
      const x0 = t.minX + tx * t.tileSize + c0 * t.spacing;
      const z0 = t.minZ + tz * t.tileSize + r0 * t.spacing;
      const x1 = t.minX + tx * t.tileSize + c1 * t.spacing;
      const z1 = t.minZ + tz * t.tileSize + r1 * t.spacing;
      this.markDirty(navGrowXZ({ min: { x: x0, y: 0, z: z0 }, max: { x: x1, y: 0, z: z1 } }, t.spacing), 'terrain edit');
    }
  }

  /** Records the terrain as the navmesh sees it now (build). */
  private seeTerrain(): void {
    const t = this.world.terrain;
    this.seenVersion = Uint32Array.from(t.version);
    this.seenHeights = t.heights.map((h) => Float32Array.from(h));
  }

  /** Builds tile (tx, tz) of the layer from the baked set and the live terrain, swaps it in, bumps its version. */
  private rebuildTile(L: LayerRt, tx: number, tz: number, sc: Scratch): void {
    const s = L.spec;
    const tile = tz * s.tilesX + tx;
    const rect: NavRect = {
      x0: s.origX + tx * s.tcs - s.border,
      z0: s.origZ + tz * s.tcs - s.border,
      x1: s.origX + (tx + 1) * s.tcs + s.border,
      z1: s.origZ + (tz + 1) * s.tcs + s.border,
    };
    const ents = this.sortedBaked().filter((e) => navOverlapsXZ(e.aabb, rect));
    const geom = navTileGeometry(this.world.terrain, rect, ents, s.extrudeM);
    const built = buildTileData(s, tx, tz, geom.positions, geom.indices, solidsOf(s, ents), sc);
    if (built === 'failed') this.buildFailures++;
    const nm = L.navMesh;
    const old = nm.getTileRefAt(tx, tz, 0);
    if (old !== 0) {
      nm.removeTile(old);
      L.slotTile[slotOf(s, old)] = -1;
    }
    let polys: PolyOutline[] = [];
    if (built !== 'failed' && built !== null) {
      const r = nm.addTile(built.data, Detour.DT_TILE_FREE_DATA, 0);
      if (statusFailed(r.status) || r.tileRef === 0) {
        built.data.destroy(); // not added: the data is still ours
        this.buildFailures++;
      } else {
        // The navmesh owns the tile data now (DT_TILE_FREE_DATA): free only the array wrapper, not its data.
        built.data.raw.isView = true;
        Raw.destroy(built.data.raw);
        L.slotTile[slotOf(s, r.tileRef)] = tile;
        polys = built.polys;
      }
    }
    L.versions[tile]++;
    if (L.walk && L.block) {
      L.walk[tile] = walkBitmap(s, tx, tz, polys);
      L.block[tile] = blockBitmap(s, tx, tz, ents);
    }
  }

  /** The tile index of a poly ref's tile on the layer (−1 if its slot is free). */
  private tileOfRef(L: LayerRt, ref: number): number {
    return L.slotTile[slotOf(L.spec, ref)] ?? -1;
  }
}

/** ai.ts floor probes in world mode (§4.1): the per-tile bitmaps, never a recast or Rapier query (RF-23). */
export class NavWalkable implements Walkable {
  readonly world: World;

  constructor(world: World) {
    this.world = world;
  }

  /** Unused in world mode (CombatSim's mover resolves positions). */
  resolve(): void {}

  /**
   * A blocker cell (fixed, anchored or ≥ blockerMinKg entity) within `pad` of p on the ground plane (2-D: the bitmap
   * has no heights). With nav 'off' nothing is solid.
   */
  solidAt(p: V3, pad = 0): Obstacle | null {
    const nav = this.world.nav;
    return nav && nav.built ? nav.blockedCellNear(p.x, p.z, pad) : null;
  }

  /** The human layer's walk bit under (x, z). With nav 'off' (or before a build) every point is open ground. */
  isWalkable(x: number, z: number): boolean {
    const nav = this.world.nav;
    return nav && nav.built ? nav.walkBitAt(x, z) : true;
  }
}

// ---------------------------------------------------------------------------
// Layer configuration
// ---------------------------------------------------------------------------

/** Metres → voxels in one place (MAP recast §3.2: recast truncates silently): radius and height ceil, climb floor. */
function layerSpec(layer: NavLayer, index: number, t: Terrain, minY: number, maxY: number): LayerSpec {
  const T = NAV_TUNING;
  const c = T[layer];
  const cs = c.cs;
  const ch = c.ch;
  if (!(cs > 0) || !(ch > 0)) throw new Error(`NavSystem: NAV_TUNING.${layer} needs cs > 0 and ch > 0`);
  const radiusVox = Math.max(0, Math.ceil(c.radius / cs - 1e-9));
  const heightVox = Math.max(1, Math.ceil(c.height / ch - 1e-9));
  const climbVox = Math.max(0, Math.floor(c.climb / ch + 1e-9));
  const tileVox = Math.max(1, Math.floor(c.tileVox));
  const tcs = tileVox * cs;
  const sizeX = t.tilesX * t.tileSize;
  const sizeZ = t.tilesZ * t.tileSize;
  const tilesX = Math.max(1, Math.ceil(sizeX / tcs - 1e-9));
  const tilesZ = Math.max(1, Math.ceil(sizeZ / tcs - 1e-9));
  const tileBits = Math.min(Math.ceil(Math.log2(tilesX * tilesZ)), REF_MAX_TILE_BITS);
  if (tilesX * tilesZ > 1 << tileBits) throw new Error(`NavSystem: the ${layer} layer needs ${tilesX * tilesZ} tiles, over Detour's limit`);
  const borderVox = radiusVox + BORDER_PAD_VOX;
  return {
    layer,
    index,
    cs,
    ch,
    slopeDeg: c.maxSlopeDeg,
    radiusVox,
    heightVox,
    climbVox,
    tileVox,
    borderVox,
    maxEdgeVox: Math.max(0, Math.round(T.maxEdgeLenM / cs)),
    maxSimplificationError: T.maxSimplificationError,
    minRegionArea: T.minRegionArea * T.minRegionArea,
    mergeRegionArea: T.mergeRegionArea * T.mergeRegionArea,
    nvp: Math.min(Detour.DT_VERTS_PER_POLYGON, Math.max(3, Math.floor(T.maxVertsPerPoly))),
    detailSampleDist: cs * Math.max(DETAIL_SAMPLE_DIST_MIN, T.detailSampleDist),
    detailSampleMaxError: ch * T.detailSampleMaxError,
    tcs,
    border: borderVox * cs,
    origX: t.minX,
    origZ: t.minZ,
    minY,
    maxY,
    tilesX,
    tilesZ,
    tileBits,
    polyBits: REF_TILE_POLY_BITS - tileBits,
    extrudeM: layer === 'ruler' ? (heightVox - 1) * ch : null,
  };
}

function halfExtentsOf(layer: NavLayer): V3 {
  const h = NAV_TUNING[layer].halfExtents;
  return { x: h[0], y: h[1], z: h[2] };
}

/** A poly or tile ref's tile slot (Detour's `it`): bits [polyBits, polyBits + tileBits). */
function slotOf(s: LayerSpec, ref: number): number {
  return Math.floor(ref / 2 ** s.polyBits) % 2 ** s.tileBits;
}

/** The angle between two orientations, degrees. */
function turnDegrees(a: Entity['pose']['q'], b: Entity['pose']['q']): number {
  const d = Math.min(1, Math.abs(a.x * b.x + a.y * b.y + a.z * b.z + a.w * b.w));
  return (2 * Math.acos(d) * 180) / Math.PI;
}

// ---------------------------------------------------------------------------
// The tile generator (Recast's tiled sample, without the library generator's leaks)
// ---------------------------------------------------------------------------

/** WASM scratch reused by every build in the process: the build context (timers and logs off) and input arrays. */
interface Scratch {
  ctx: RecastBuildContext;
  verts: FloatArray;
  tris: IntArray;
  areas: UnsignedCharArray;
  poly: FloatArray;
}

let scratch: Scratch | null = null;

/** Created on the first build, after physicsReady() has initialised recast (nothing runs at module load). */
function recastScratch(): Scratch {
  if (scratch) return scratch;
  if (Raw.Module === undefined) throw new Error('NavSystem: recast is not initialised (await physicsReady() first)');
  scratch = { ctx: new RecastBuildContext(false), verts: new FloatArray(), tris: new IntArray(), areas: new UnsignedCharArray(), poly: new FloatArray() };
  return scratch;
}

/** An entity's inside: its footprint (convex, (x, z) pairs) between two heights of walkable floor. */
interface Solid {
  footprint: Float64Array;
  hmin: number;
  hmax: number;
}

/**
 * The insides of a tile's entities: walkable floor inside an entity's footprint, from a voxel under its bottom to a
 * voxel under its top, is not ground (the inside of a box, the ground under a log, a boulder's flanks). Floor within a
 * voxel of an entity's top stays (the top of a box or a log is something to stand on), and so does an entity too thin
 * to have an inside (a cover slab, a branch), so a covered pit's cover stays walkable. An extruded blocker's inside is
 * its extrusion's (its footprint up to extrudeM).
 */
function solidsOf(s: LayerSpec, ents: readonly NavEntityInput[]): Solid[] {
  const out: Solid[] = [];
  for (const e of ents) {
    if (e.footprint.length < 6) continue;
    const hmin = e.aabb.min.y - s.ch;
    const top = s.extrudeM !== null && e.extrude ? e.aabb.min.y + s.extrudeM : e.aabb.max.y;
    const hmax = top - s.ch;
    if (hmax >= hmin) out.push({ footprint: e.footprint, hmin, hmax });
  }
  return out;
}

/** A polygon's outline on the ground plane, (x, z) pairs as Detour stores the tile's vertices (float32). */
type PolyOutline = Float64Array;

/**
 * One tile's Detour data from its input triangles, or null when nothing walkable is left, or 'failed' on a recast
 * error. Also returns the polygons' outlines (the walk bitmap's input).
 */
function buildTileData(
  s: LayerSpec,
  tx: number,
  tz: number,
  positions: Float32Array,
  indices: Int32Array,
  solids: readonly Solid[],
  sc: Scratch,
): { data: UnsignedCharArray; polys: PolyOutline[] } | null | 'failed' {
  const ctx = sc.ctx;
  const bmin: [number, number, number] = [s.origX + tx * s.tcs - s.border, s.minY, s.origZ + tz * s.tcs - s.border];
  const bmax: [number, number, number] = [s.origX + (tx + 1) * s.tcs + s.border, s.maxY, s.origZ + (tz + 1) * s.tcs + s.border];
  const size = s.tileVox + 2 * s.borderVox;
  const nt = indices.length / 3;
  if (nt === 0) return null;
  let hf: RecastHeightfield | null = allocHeightfield();
  let chf: RecastCompactHeightfield | null = null;
  let cset: RecastContourSet | null = null;
  let pmesh: RecastPolyMesh | null = null;
  let dmesh: RecastPolyMeshDetail | null = null;
  try {
    if (!createHeightfield(ctx, hf, size, size, bmin, bmax, s.cs, s.ch)) return 'failed';
    const nv = positions.length / 3;
    sc.verts.copy(positions);
    sc.tris.copy(indices);
    sc.areas.resize(nt);
    sc.areas.getHeapView().fill(0);
    markWalkableTriangles(ctx, s.slopeDeg, sc.verts, nv, sc.tris, nt, sc.areas);
    if (!rasterizeTriangles(ctx, sc.verts, nv, sc.tris, sc.areas, nt, hf, s.climbVox)) return 'failed';
    filterLowHangingWalkableObstacles(ctx, s.climbVox, hf);
    filterLedgeSpans(ctx, s.heightVox, s.climbVox, hf);
    filterWalkableLowHeightSpans(ctx, s.heightVox, hf);
    chf = allocCompactHeightfield();
    if (!buildCompactHeightfield(ctx, s.heightVox, s.climbVox, hf, chf)) return 'failed';
    freeHeightfield(hf);
    hf = null;
    // Entities are solid: nothing inside one is ground (Recast sees only their surfaces), and the erosion below then
    // keeps agents a radius away from them as from any wall.
    for (const v of solids) {
      const n = v.footprint.length / 2;
      const xyz = new Float32Array(n * 3);
      for (let k = 0; k < n; k++) {
        xyz[k * 3] = v.footprint[k * 2];
        xyz[k * 3 + 2] = v.footprint[k * 2 + 1];
      }
      sc.poly.copy(xyz);
      markConvexPolyArea(ctx, sc.poly, n, v.hmin, v.hmax, Recast.RC_NULL_AREA, chf);
    }
    if (!erodeWalkableArea(ctx, s.radiusVox, chf)) return 'failed';
    if (!buildDistanceField(ctx, chf)) return 'failed';
    if (!buildRegions(ctx, chf, s.borderVox, s.minRegionArea, s.mergeRegionArea)) return 'failed';
    cset = allocContourSet();
    if (!buildContours(ctx, chf, s.maxSimplificationError, s.maxEdgeVox, cset, Recast.RC_CONTOUR_TESS_WALL_EDGES)) return 'failed';
    pmesh = allocPolyMesh();
    if (!buildPolyMesh(ctx, cset, s.nvp, pmesh)) return 'failed';
    dmesh = allocPolyMeshDetail();
    if (!buildPolyMeshDetail(ctx, pmesh, chf, s.detailSampleDist, s.detailSampleMaxError, dmesh)) return 'failed';
    const npolys = pmesh.npolys();
    if (npolys === 0) return null;
    for (let i = 0; i < npolys; i++) {
      if (pmesh.areas(i) === Recast.RC_WALKABLE_AREA) pmesh.setAreas(i, 0);
      if (pmesh.areas(i) === 0) pmesh.setFlags(i, POLY_FLAGS_WALK);
    }
    const params = new NavMeshCreateParams();
    let created: { success: boolean; navMeshData: UnsignedCharArray };
    try {
      params.setPolyMeshCreateParams(pmesh);
      params.setPolyMeshDetailCreateParams(dmesh);
      params.setWalkableHeight(s.heightVox * s.ch);
      params.setWalkableRadius(s.radiusVox * s.cs);
      params.setWalkableClimb(s.climbVox * s.ch);
      params.setCellSize(s.cs);
      params.setCellHeight(s.ch);
      params.setBuildBvTree(true);
      params.setTileX(tx);
      params.setTileY(tz);
      created = createNavMeshData(params);
    } finally {
      Raw.destroy(params.raw);
    }
    if (!created.success) {
      created.navMeshData.destroy();
      return 'failed';
    }
    return { data: created.navMeshData, polys: polyOutlines(pmesh) };
  } finally {
    if (hf) freeHeightfield(hf);
    if (chf) freeCompactHeightfield(chf);
    if (cset) freeContourSet(cset);
    if (pmesh) freePolyMesh(pmesh);
    if (dmesh) freePolyMeshDetail(dmesh);
  }
}

/**
 * The polygons of a poly mesh as world (x, z) outlines, computed as Detour computes the tile's vertices
 * (bmin + v·cs in float32), so the walk bitmap and isWalkable's polygon queries measure the same polygons.
 */
function polyOutlines(pmesh: RecastPolyMesh): PolyOutline[] {
  const f = Math.fround;
  const bmin = pmesh.bmin();
  const cs = f(pmesh.cs());
  const bx = f(bmin.x);
  const bz = f(bmin.z);
  const nvp = pmesh.nvp();
  const nullIdx = Recast.RC_MESH_NULL_IDX;
  const out: PolyOutline[] = [];
  for (let i = 0; i < pmesh.npolys(); i++) {
    const pts: number[] = [];
    for (let j = 0; j < nvp; j++) {
      const v = pmesh.polys(i * 2 * nvp + j);
      if (v === nullIdx) break;
      pts.push(f(bx + f(pmesh.verts(v * 3) * cs)), f(bz + f(pmesh.verts(v * 3 + 2) * cs)));
    }
    out.push(Float64Array.from(pts));
  }
  return out;
}

// ---------------------------------------------------------------------------
// The human layer's bitmaps (§4.1, RF-23)
// ---------------------------------------------------------------------------

function bitAt(bits: Uint8Array, bit: number): boolean {
  return (bits[bit >> 3] & (1 << (bit & 7))) !== 0;
}

function setBit(bits: Uint8Array, bit: number): void {
  bits[bit >> 3] |= 1 << (bit & 7);
}

/** The tile and bit of world cell (ci, cj) of the layer's cs grid; null outside the grid. */
function cellAt(s: LayerSpec, ci: number, cj: number): { tile: number; bit: number } | null {
  const tx = Math.floor(ci / s.tileVox);
  const tz = Math.floor(cj / s.tileVox);
  if (tx < 0 || tz < 0 || tx >= s.tilesX || tz >= s.tilesZ) return null;
  return { tile: tz * s.tilesX + tx, bit: (cj - tz * s.tileVox) * s.tileVox + (ci - tx * s.tileVox) };
}

function cellOf(s: LayerSpec, x: number, z: number): { tile: number; bit: number } | null {
  return cellAt(s, Math.floor((x - s.origX) / s.cs), Math.floor((z - s.origZ) / s.cs));
}

/** Walk bits of tile (tx, tz): a cell is set when one of the tile's polygons lies within walkReachM of its centre. */
function walkBitmap(s: LayerSpec, tx: number, tz: number, polys: readonly PolyOutline[]): Uint8Array {
  const n = s.tileVox;
  const bits = new Uint8Array(Math.ceil((n * n) / 8));
  const reach = NAV_TUNING.walkReachM + WALK_REACH_TOL;
  const x0 = s.origX + tx * s.tcs;
  const z0 = s.origZ + tz * s.tcs;
  for (const poly of polys) {
    let px0 = Infinity;
    let px1 = -Infinity;
    let pz0 = Infinity;
    let pz1 = -Infinity;
    for (let k = 0; k < poly.length; k += 2) {
      px0 = Math.min(px0, poly[k]);
      px1 = Math.max(px1, poly[k]);
      pz0 = Math.min(pz0, poly[k + 1]);
      pz1 = Math.max(pz1, poly[k + 1]);
    }
    const i0 = Math.max(0, Math.floor((px0 - reach - x0) / s.cs - 0.5));
    const i1 = Math.min(n - 1, Math.ceil((px1 + reach - x0) / s.cs - 0.5));
    const j0 = Math.max(0, Math.floor((pz0 - reach - z0) / s.cs - 0.5));
    const j1 = Math.min(n - 1, Math.ceil((pz1 + reach - z0) / s.cs - 0.5));
    for (let j = j0; j <= j1; j++) {
      for (let i = i0; i <= i1; i++) {
        const bit = j * n + i;
        if (bitAt(bits, bit)) continue;
        const cx = s.origX + (tx * n + i + 0.5) * s.cs;
        const cz = s.origZ + (tz * n + j + 0.5) * s.cs;
        if (navWithinPolygonXZ(poly, cx, cz, reach)) setBit(bits, bit);
      }
    }
  }
  return bits;
}

/**
 * Blocker bits of tile (tx, tz): the footprints of the baked blockers (fixed, anchored or ≥ blockerMinKg) rasterised at
 * cs; a cell is set when a footprint comes within half a cell of its centre (so a 10 cm stake still marks its cell).
 */
function blockBitmap(s: LayerSpec, tx: number, tz: number, ents: readonly NavEntityInput[]): Uint8Array {
  const n = s.tileVox;
  const bits = new Uint8Array(Math.ceil((n * n) / 8));
  const half = s.cs / 2;
  const x0 = s.origX + tx * s.tcs;
  const z0 = s.origZ + tz * s.tcs;
  for (const e of ents) {
    if (!e.blocker || e.footprint.length === 0) continue;
    const a: NavAabb = e.aabb;
    const i0 = Math.max(0, Math.floor((a.min.x - half - x0) / s.cs - 0.5));
    const i1 = Math.min(n - 1, Math.ceil((a.max.x + half - x0) / s.cs - 0.5));
    const j0 = Math.max(0, Math.floor((a.min.z - half - z0) / s.cs - 0.5));
    const j1 = Math.min(n - 1, Math.ceil((a.max.z + half - z0) / s.cs - 0.5));
    for (let j = j0; j <= j1; j++) {
      for (let i = i0; i <= i1; i++) {
        const bit = j * n + i;
        if (bitAt(bits, bit)) continue;
        const cx = s.origX + (tx * n + i + 0.5) * s.cs;
        const cz = s.origZ + (tz * n + j + 0.5) * s.cs;
        if (navWithinPolygonXZ(e.footprint, cx, cz, half)) setBit(bits, bit);
      }
    }
  }
  return bits;
}
